/**
 * Permission-related type definitions
 *
 * The Android and iOS catalogs (`src/categorized-*-permissions.json`) are
 * generated by `scripts/build-permission-catalog.js` from the SDK data and the
 * curated overlays in `src/permission-sources/`. Do not hand-edit them.
 */

/** Who can actually hold an Android permission. */
export type AndroidPermissionAudience = 'app' | 'system';

/** Where an Android permission comes from. */
export type AndroidPermissionSource = 'android' | 'health' | 'vendor';

/** An SDK-gated way of declaring a permission (written as attributes on the element). */
export interface AndroidPermissionVariant {
    maxSdkVersion?: number;
    minSdkVersion?: number;
    usesPermissionFlags?: string;
    note: string;
}

/** Android permission data structure (catalog entry) */
export interface AndroidPermission {
    permission: string;
    description: string;
    protectionLevel: string;
    constantValue: string;
    category: string;
    /** API level that introduced the permission (floor of the SDK `since`, e.g. "36.1" -> 36). */
    apiLevel: number;
    /** Exact SDK `since` when it is a minor SDK release ("36.1", "37.0"). */
    apiLevelExact?: string;
    deprecatedIn?: number | null;
    removedIn?: number | null;
    permissionGroup?: string;
    audience?: AndroidPermissionAudience;
    source?: AndroidPermissionSource;
    /** Successor permissions, e.g. READ_EXTERNAL_STORAGE -> READ_MEDIA_IMAGES/VIDEO/AUDIO. */
    replacedBy?: string[];
    /** SDK-gated variants worth declaring. */
    recommended?: AndroidPermissionVariant[];
    /** Permissions that should be declared together. */
    pairsWith?: string[];
    /** Google Play policy note for restricted permissions. */
    playPolicy?: string;
    equivalentIosPermissions?: string[];
}

/** A `<uses-permission>` / `<uses-permission-sdk-23>` element as the writer sees it. */
export interface AndroidPermissionEntry {
    /** Full permission name (`android.permission.CAMERA`). Short names are prefixed with `android.permission.`. */
    name: string;
    maxSdkVersion?: number;
    minSdkVersion?: number;
    usesPermissionFlags?: string;
    /** Emit `<uses-permission-sdk-23>` (only granted on API 23+). */
    sdk23?: boolean;
    /** `tools:node` value; `remove` entries are never counted as used. */
    toolsNode?: 'remove' | 'replace' | 'merge' | 'strict' | 'merge-only-attributes' | 'removeAll';
    /** Other `tools:*` attributes, kept verbatim (`tools:targetApi`...). */
    toolsAttributes?: Record<string, string>;
}

/** What the extractor returns for each element found in a manifest. */
export interface UsedAndroidPermission extends AndroidPermission {
    /** The element as written in the manifest (attributes, sdk-23, tools:*). */
    entry: AndroidPermissionEntry;
    /** `tools:node="remove"`: the merger strips it from the final manifest. */
    mergerRemoved: boolean;
    /** Not in the catalog; kept as-is so a save never drops it. */
    unknown?: boolean;
}

/** iOS Info.plist value kinds handled by the writer. */
export type IOSPermissionType = 'string' | 'boolean' | 'array' | 'dictionary';

/** A plist array/dictionary value. Arrays hold strings; dictionaries map keys to strings. */
export type IOSPermissionValue = string | boolean | string[] | Record<string, string>;

/** iOS permission data structure */
export interface IOSPermission {
    permission: string;
    description: string;
    type: IOSPermissionType | string;
    category: string;
    value?: IOSPermissionValue;
    /** First iOS release that reads the key. */
    minOS?: string;
    /** First macOS release that reads the key (macOS-only keys have no `minOS`). */
    minMacOS?: string;
    deprecatedInOS?: string;
    replacedBy?: string[];
    pairsWith?: string[];
    equivalentAndroidPermissions?: string[];
    podfileMacro?: string;
    /** Not in the catalog; kept so a save never drops it. */
    unknown?: boolean;
}

/** iOS permission entry for saving */
export interface IOSPermissionEntry {
    permission: string;
    value?: IOSPermissionValue;
    type?: IOSPermissionType | string;
    podfileMacro?: string;
}

/** Cross-platform permission mapping */
export interface PermissionMapping {
    androidToIos: Record<string, string[]>;
    iosToAndroid: Record<string, string[]>;
    /** Android permissions whose iOS side is a Podfile macro rather than an Info.plist key. */
    androidToIosPodfileMacros?: Record<string, { podfileMacro: string; note: string }>;
}

/** Categorized permission groups */
export interface CategorizedPermissions<T> {
    [category: string]: T[];
}

/** Permission with podfile macro info */
export interface IOSPermissionWithMacro {
    permission: string;
    podfileMacro?: string;
}
